키로거는 사용자 활동을 기록하는 소프트웨어입니다. 사용자 활동을 기록하는 목적으로 사용하는 스크립트는 다음과 같습니다.

**키로거 스크립트 예시**

```javascript
// 사용자 활동을 기록하는 함수
function logActivity(activity) {
  // 로그 파일에 기록
  const fs = require('fs');
  const logFile = 'activity.log';
  const timestamp = new Date().toISOString();
  const message = `${timestamp} - ${activity}\n`;
  fs.appendFile(logFile, message, (err) => {
    if (err) {
      console.error(err);
   }
  });
}

// 사용자 활동을 기록
logActivity('로그인');
logActivity('페이지 이동');
logActivity('검색어 입력');
```

